using System;
using System.Collections;
using System.Reflection;
using UnityEditor;
using UnityEngine;
namespace RollerSort.Editor {
 [InitializeOnLoad] public static class ReferenceMechanicsCheck {
  const BindingFlags F=BindingFlags.Instance|BindingFlags.NonPublic;static RollerGame game;static int stage;static double started,ready;static int count;static object portal;static int errors;
  static ReferenceMechanicsCheck(){Application.logMessageReceived+=(m,s,t)=>{if(t==LogType.Exception&&s.Contains("RollerSort"))errors++;};if(SessionState.GetBool("ReferenceRulesQA",false)){started=EditorApplication.timeSinceStartup;EditorApplication.update+=Tick;}}
  public static void Run(){
   var floor=new bool[3,3];var blocked=new bool[3,3];for(int r=0;r<3;r++)for(int c=0;c<3;c++)floor[r,c]=true;blocked[0,0]=blocked[0,1]=blocked[1,1]=true;Require(BoardAccess.TouchesExit(BoardAccess.Reachable(floor,blocked),1,1),"Side path must reveal a box with occupied cell below");blocked[0,2]=true;Require(!BoardAccess.TouchesExit(BoardAccess.Reachable(floor,blocked),1,1),"Stone/sealed bottom must block side access");
   BeltSpacingCheck.Run();var travel=BeltTrack.Point(-.263f*.1f)-BeltTrack.Point(0);Require(travel.x<0&&Mathf.Abs(travel.magnitude/.1f-166)<2,"Reference belt direction/speed");
   int[] counts=new int[10];for(int r=0;r<5;r++)for(int c=0;c<5;c++)if(LevelLayouts.Cell(19,r,c)=='#')counts[LevelLayouts.SourceColor(19,r,c,0)]+=3;foreach(int c in new[]{0,4})foreach(int colour in LevelLayouts.TunnelColors(19,c,null))counts[colour]+=3;foreach(var q in ReferenceLevel19.ReceiverQueues())foreach(int colour in q)counts[colour]--;foreach(int n in counts)Require(n==0,"Level 19 source/receiver colour totals differ");
   SessionState.SetInt("RefOldLevel",PlayerPrefs.GetInt("level",1));SessionState.SetInt("RefOldCoins",PlayerPrefs.GetInt("coins",500));SessionState.SetInt("RefOldVisited",PlayerPrefs.GetInt("visitedJourney",0));PlayerPrefs.SetInt("level",19);PlayerPrefs.SetInt("visitedJourney",0);SessionState.SetBool("ReferenceRulesQA",true);started=EditorApplication.timeSinceStartup;UnityEditor.SceneManagement.EditorSceneManager.OpenScene("Assets/RollerSort/Scenes/RollerSort.unity");EditorApplication.update+=Tick;EditorApplication.isPlaying=true;
  }
  static object Get(string n)=>typeof(RollerGame).GetField(n,F).GetValue(game);static void Set(string n,object v)=>typeof(RollerGame).GetField(n,F).SetValue(game,v);static void Call(string n,params object[] args)=>typeof(RollerGame).GetMethod(n,F).Invoke(game,args);static object Field(object o,string n)=>o.GetType().GetField(n).GetValue(o);static void Require(bool b,string m){if(!b)throw new Exception(m);}
  static object Box(int row,int col){foreach(var b in (IList)Get("boxes"))if(!(bool)Field(b,"removed")&&(int)Field(b,"row")==row&&(int)Field(b,"col")==col)return b;return null;}
  static void Tick(){try{if(EditorApplication.timeSinceStartup-started>30)throw new Exception("Reference mechanics timeout");if(!EditorApplication.isPlaying)return;EditorApplication.QueuePlayerLoopUpdate();Application.runInBackground=true;game=UnityEngine.Object.FindFirstObjectByType<RollerGame>();if(!game||Get("game")==null)return;
   if(stage==0){game.StopAllCoroutines();game.enabled=false;Set("diagnosticsActive",true);Set("level",19);Call("BuildLevel");Set("capacity",10000);Call("Release",Box(0,4));Call("Release",Box(1,4));Call("Release",Box(2,4));portal=((IList)Get("portals"))[0];foreach(var p in (IList)Get("portals"))if((int)Field(p,"col")==4)portal=p;ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(EditorApplication.timeSinceStartup-ready<.8)return;
   if(stage>=1&&stage<=3){var source=Box(2,4);Require(source!=null,"Portal output missing");Require(!(bool)Field(source,"emerging"),"Portal animation did not finish");var output=(RectTransform)Field(source,"view");foreach(Transform sibling in output.parent)if(sibling.name=="slot")Require(sibling.GetSiblingIndex()<output.GetSiblingIndex(),"Floor slot obscures tunnel output");Require((int)Field(source,"color")==new[]{6,3,8}[stage-1],"Portal colour order");Require((int)Field(portal,"row")==3,"Tunnel moved out of fixed cell");var q=(System.Collections.Generic.Queue<int>)Field(portal,"next");Require(q.Count==3-stage,"Tunnel counter mismatch");var side=Box(1,3);Require((bool)typeof(RollerGame).GetMethod("Accessible",F).Invoke(game,new[]{side}),"Side access above stone failed");Call("Release",source);ready=EditorApplication.timeSinceStartup;stage++;return;}
   if(stage==4){Require(Box(2,4)==null,"Empty tunnel spawned an extra box");Require(((IList)Get("stones")).Count==1,"Stone disappeared");Require(((IList)Get("portals")).Count==2,"Fixed portals disappeared");Finish(true,null);}
  }catch(Exception e){Finish(false,e);}}
  static void Finish(bool ok,Exception e){PlayerPrefs.SetInt("level",SessionState.GetInt("RefOldLevel",1));PlayerPrefs.SetInt("coins",SessionState.GetInt("RefOldCoins",500));PlayerPrefs.SetInt("visitedJourney",SessionState.GetInt("RefOldVisited",0));PlayerPrefs.Save();SessionState.SetBool("ReferenceRulesQA",false);EditorApplication.update-=Tick;if(errors>0){ok=false;e=new Exception("Runtime exceptions: "+errors);}if(ok)Debug.Log("ROLLER_REFERENCE_RULES_OK: side accessibility, stone, fixed portals 3→2→1→0, output sequence, belt speed/direction and colour conservation.");else Debug.LogException(e);EditorApplication.Exit(ok?0:1);}
 }
}
